async function runBackend(options = {}) {
  const issue = await inspectStartupDatabase();
  const recovery = issue ? await confirmStartupRecovery(issue) : undefined;
  if (recovery === null) return;
  try {
    return await backend(options);
  } catch (error) {
    if (recovery?.failed) recovery.failed(error);
    else throw error;
  }
}

