      if (
        saved &&
        cdpOptionsKey(saved) !== cdpOptionsKey(options) &&
        cdpConnectionMode(saved) === "local" &&
        (await cdpVersion(persistent.port))
      )
        throw cdpOptionsConflict(browser);
      cdpBrowserOptions.set(browser, options);
      const mode = cdpConnectionMode(options);
      persistent.user_data_dir =
        mode === "local" || mode === "extension" ? options.user_data_dir : null;
      if (mode !== "local") persistent.port = mode === "port" ? options.port : null;
      if (mode === "reverse" || mode === "extension") {
        const record = await cdpOpenConnection(persistent, null);
        cdpBrowsers.set(browser, record);
        return record;
      }
      let version =
        mode === "websocket"
          ? { webSocketDebuggerUrl: options.websocket_url }
          : mode === "local"
            ? await cdpVersion(persistent.port)
            : await cdpVersion(cdpDiscoveryUrl(options), options.connect_timeout_ms);
      if (!version && mode !== "local")
        throw new Error(`Unable to discover CDP browser '${browser}' through ${mode} attachment`);
      if (!version) version = await cdpLaunchBrowser(persistent);
      const record = await cdpOpenConnection(persistent, version);
      cdpBrowsers.set(browser, record);
      return record;
