      goal: context.goal_text,
      timeout_seconds: Number(context.goal_timeout_seconds),
      status: !chatGoalsEnabled() ? "disabled" : context.goal_status,
      chatgpt_chat_id: context.chatgpt_chat_id || null,
      chat_url: context.chatgpt_chat_id ? chatGoalUrl(context.chatgpt_chat_id) : null,
      next_check_at:
        chatGoalsEnabled() && context.goal_text && context.goal_next_check_at
