    if (shuttingDown) return;
    if (!CHAT_GOAL_STATUSES.includes(status)) status = "error";
    if (
      !context.chatgpt_chat_id &&
      !["pending", "matching", "disabled", "expired"].includes(status)
    ) {
      next = 0;
      detail = `${String(detail).slice(0, 350)} Call chat_set_goal again to retry matching.`.trim();
    }
    await run(
      `UPDATE contexts SET goal_status=?,goal_error=?,goal_next_check_at=? WHERE id=? AND goal_revision=? AND goal_text<>''`,
      status,
      String(detail).slice(0, 500),
      next,
      context.id,
      context.goal_revision,
    );
    changed({ ui: ["sessions"] }, "chat-goal-state");
