    const context = await one("SELECT * FROM contexts WHERE handle=?", handle);
    if (!context || contextExpired(context)) return;
    await run(
      `UPDATE contexts SET goal_activity_at=? WHERE goal_text<>'' AND (handle=? OR (chatgpt_chat_id<>'' AND chatgpt_chat_id=?))`,
      Date.now(),
      handle,
      context.chatgpt_chat_id,
    );
