      busy:
        '[data-testid="stop-button"],[data-testid="composer-stop-button"],' +
        '[data-is-streaming="true"],[data-state="streaming"],' +
        '[data-message-author-role="assistant"][aria-busy="true"]',
      history: 'nav,[role="navigation"],aside,#history',
