        ...searchScopeOutput(selection, root, dir),
        engine: "rag.js",
        storage: "turso",
        mode,
        gitignore: args.gitignore !== false,
        indexed_files: eligible.length,
        indexed_chunks: null,
        index_counts: indexStatus.counts,
        reindexed_files: report.updated,
        unchanged_files: report.unchanged,
        removed_files: report.removed + prunedIgnored,
        scanned_files: scanned,
        truncated: truncated || !report.complete,
        error_count: errors.length,
        errors: errors.slice(0, 100),
        returned: results.length,
