    if (encoded) {
      try {
        return basename(decodeURIComponent(encoded.trim().replace(/^"|"$/g, "")));
      } catch {}
    }
    const plain = disposition.match(/filename\s*=\s*"?([^";]+)"?/i)?.[1];
    if (plain) return basename(plain.trim());
