async function desktop() {
  let native;
  let renderer;
  let pump;
  let resolveClosed;
  let rejectClosed;
  let closing = false;
  let startup;
  let runtime;
  const closed = new Promise((resolve, reject) => {
    resolveClosed = resolve;
    rejectClosed = reject;
  });
  desktopHost = {
    input: () => {},
    cancelStartup: null,
    close: resolveClosed,
    render: (payload) => {
      if (!closing) {
        if (native?.section === "startup" && payload.section !== "startup") native.revision = 0;
        native?.apply(payload);
      }
    },
  };
  try {
    // GPUI initializes first on this thread. Backend and GUI share the Bun
    // event loop; database I/O uses the public asynchronous Turso interface.
    const { GpuixRenderer } = await loadRuntimePackage("@gpuix/native");
    renderer = new GpuixRenderer((error, event) => {
      if (error) {
        console.error("GPUI event error", error);
        return;
      }
      if (closing) return;
      try {
        native?.dispatch(event);
      } catch (error) {
        console.error("Native UI input failed", error);
      }
    });
    renderer.init({
      title: "MrMCP " + VERSION,
      appName: "MrMCP",
      appId: "com.mefistofelix.mrmcp",
      width: 1180,
      height: 760,
      minWidth: 900,
      minHeight: 620,
    });
    renderer.setWindowKeyEvents(true, false, 0);
    native = await NativeUiHost.create(renderer, (event) => {
      Promise.resolve(desktopHost.input(event)).catch(rejectClosed);
    });
    native.apply({
      revision: 0,
      section: "startup",
      projection: nativeProjection(
        <div id="app">
          <header>
            <b>MrMCP</b>
          </header>
          <main>
            <h2>Starting…</h2>
          </main>
        </div>,
      ),
    });
    renderer.activateWindow();
    const nativeRuntime = await loadRuntimePackage("@gpuix/native/runtime");
    pump = nativeRuntime.startFrameLoop(renderer, {
      onTerminated: resolveClosed,
      onError: rejectClosed,
    });
    startup = runBackend()
      .then(async (service) => {
        runtime = service;
        if (!service) return;
        if (closing) {
          await service.shutdown();
          return;
        }
        desktopHost.cancelStartup = null;
        desktopHost.input = service.input;
        service.visible(true);
        await service.input({ type: "bootstrap" });
      })
      .catch((error) => {
        if (!closing) rejectClosed(error);
        else console.error("Desktop startup stopped", error);
      });
    await closed;
  } finally {
    closing = true;
    pump?.stop();
    native?.close();
    desktopHost.input = () => {};
    desktopHost.cancelStartup?.();
    runtime?.visible(false);
    if (startup) await waitFor(startup, 5000, null);
    if (runtime) await waitFor(runtime.shutdown(), 5000, null);
    desktopHost = null;
  }
}
function openExternalUrl(value) {
  const url = new URL(String(value));
  if (!["http:", "https:"].includes(url.protocol))
    throw new Error("Only HTTP(S) links may be opened");
  const [program, args] =
    RUNTIME_OS === "windows"
      ? ["rundll32.exe", ["url.dll,FileProtocolHandler", url.href]]
      : RUNTIME_OS === "darwin"
        ? ["open", [url.href]]
        : ["xdg-open", [url.href]];
  const child = nodeSpawn(program, args, { windowsHide: true, stdio: "ignore", detached: true });
  child.on("error", (error) => console.error("Open URL failed", error));
  child.unref();
}
export { nativeElement, NativeFragment, nativeProjection, NativeUiHost };

if (import.meta.main) {
  if (process.argv.slice(2)[0] === "--add-workspace") {
    if (process.argv.slice(2).length !== 3) {
      console.error("Usage: mrmcp --add-workspace <name> <path>");
      process.exit(2);
    }
    try {
      await runBackend({
        addWorkspace: { name: process.argv.slice(2)[1], path: process.argv.slice(2)[2] },
      });
    } catch (error) {
      console.error(errorMessage(error));
      process.exit(1);
    }
    process.exit(0);
  }
  if (process.argv.slice(2).includes("--backend")) await runBackend();
  else {
    await desktop();
    process.exit(0);
  }
}
